	public function index()
	{
        $values= array('titre'=>'Notes');
        $c=classe::orderBy('nom')->get();
        if(session('success')){
            $values['success']=session('success');
            Session::forget('success');
        }
        $cy=cycle::all();
        $n=niveau::all();
        $nn=NNiveau::all();
        $values['niveaux']=$n;
        $values['classes']=$c;
        $values['nniveaux']=$nn;
        $values['cycles']=$cy;

        return view('eleves/classe_note',$values);
	}

private function enregistrerGenerationPV(
    $classe,
    $cycle,
    $nniveau,
    $annee,
    $semestre,
    $typePv,
    $results,
    $dateDebut = null,
    $dateFin = null
) {
    return $this->savePvGenerationRecord($classe, $cycle, $nniveau, $annee, $semestre, $typePv, count($results), $dateDebut, $dateFin);
}
public function savePvGeneration(Request $request)
{
    try {
        $this->validate($request, array(
            'id_classe' => 'required|integer',
            'id_cycle' => 'required|integer',
            'id_nniveau' => 'required|integer',
            'annee_academique' => 'required',
            'semestre' => 'required',
            'type_pv' => 'required',
            'nombre_etudiants' => 'required|integer',
            'date_debut' => 'sometimes|date',
            'date_fin' => 'sometimes|date'
        ));

        if (!empty($request->date_debut) && !empty($request->date_fin) && strtotime($request->date_fin) < strtotime($request->date_debut)) {
            return response()->json(array(
                'success' => false,
                'message' => 'La date de fin doit etre superieure ou egale a la date de debut.'
            ), 422);
        }

        $nomFichier = 'PV_'.strtoupper($request->type_pv).'_SEMESTRE_'.$request->semestre.'_'.date('Ymd_His').'.xlsx';
        $now = date('Y-m-d H:i:s');
        $idPv = DB::table('pv_generations')->insertGetId(array(
            'id_classe' => $request->id_classe,
            'id_cycle' => $request->id_cycle,
            'id_nniveau' => $request->id_nniveau,
            'annee_academique' => $request->annee_academique,
            'semestre' => $request->semestre,
            'type_pv' => strtolower($request->type_pv),
            'date_debut' => $request->date_debut,
            'date_fin' => $request->date_fin,
            'date_generation' => $now,
            'nombre_etudiants' => $request->nombre_etudiants,
            'nom_fichier' => $nomFichier,
            'id_user' => Auth::check() ? Auth::id() : null,
            'statut' => 'genere',
            'created_at' => $now,
            'updated_at' => $now
        ));

        return response()->json(array(
            'success' => true,
            'message' => 'PV enregistre avec succes.',
            'id_pv' => $idPv,
            'date_generation' => date('d/m/Y H:i', strtotime($now)),
            'nom_fichier' => $nomFichier
        ));
    } catch (\Exception $e) {
        return response()->json(array(
            'success' => false,
            'message' => 'Erreur lors de l\'enregistrement du PV : '.$e->getMessage()
        ), 500);
    }
}
