    public function historiquePv(Request $request, $id_classe)
{
    /*
    |--------------------------------------------------------------------------
    | PARAMETRES
    |--------------------------------------------------------------------------
    */

    $id_cycle = $request->input('cycle');

    $id_nniveau = $request->input('nniveau');


    /*
    |--------------------------------------------------------------------------
    | SPECIALITE / CLASSE
    |--------------------------------------------------------------------------
    */

    $classe = classe::find($id_classe);

    if (!$classe) {
        abort(404, 'Spécialité introuvable.');
    }


    /*
    |--------------------------------------------------------------------------
    | CYCLE
    |--------------------------------------------------------------------------
    */

    $cycle = null;

    if (!empty($id_cycle)) {
        $cycle = cycle::find($id_cycle);
    }


    /*
    |--------------------------------------------------------------------------
    | NIVEAU
    |--------------------------------------------------------------------------
    */

    $nniveau = null;

    if (!empty($id_nniveau)) {
        $nniveau = NNiveau::find($id_nniveau);
    }


    /*
    |--------------------------------------------------------------------------
    | REQUETE DE BASE
    |--------------------------------------------------------------------------
    */

    $query = PvGeneration::where(
        'id_classe',
        $id_classe
    );


    /*
    |--------------------------------------------------------------------------
    | CYCLE
    |--------------------------------------------------------------------------
    */

    if (!empty($id_cycle)) {

        $query->where(
            'id_cycle',
            $id_cycle
        );
    }


    /*
    |--------------------------------------------------------------------------
    | NIVEAU
    |--------------------------------------------------------------------------
    */

    if (!empty($id_nniveau)) {

        $query->where(
            'id_nniveau',
            $id_nniveau
        );
    }


    /*
    |--------------------------------------------------------------------------
    | ANNEE ACADEMIQUE
    |--------------------------------------------------------------------------
    */

    if (
        $request->has('annee_academique')
        &&
        $request->input('annee_academique') != ''
    ) {

        $query->where(
            'annee_academique',
            $request->input('annee_academique')
        );
    }


    /*
    |--------------------------------------------------------------------------
    | FORMAT BTS / HND
    |--------------------------------------------------------------------------
    */

    if (
        $request->has('type_pv')
        &&
        $request->input('type_pv') != ''
    ) {

        $query->where(
            'type_pv',
            $request->input('type_pv')
        );
    }


    /*
    |--------------------------------------------------------------------------
    | TYPE DU DOCUMENT
    |--------------------------------------------------------------------------
    |
    | semestre 1 = 1
    | semestre 2 = 2
    | bilan annuel = 9
    |
    */

    if (
        $request->has('categorie')
        &&
        $request->input('categorie') != ''
    ) {

        $categorie =
            $request->input('categorie');


        if ($categorie == 'semestriel') {

            $query->whereIn(
                'semestre',
                array(1, 2)
            );

        } elseif ($categorie == 'annuel') {

            $query->where(
                'semestre',
                9
            );

        }
    }


    /*
    |--------------------------------------------------------------------------
    | SEMESTRE
    |--------------------------------------------------------------------------
    */

    if (
        $request->has('semestre')
        &&
        $request->input('semestre') != ''
    ) {

        $query->where(
            'semestre',
            $request->input('semestre')
        );
    }


    /*
    |--------------------------------------------------------------------------
    | DATE DE DEBUT
    |--------------------------------------------------------------------------
    */

    if (
        $request->has('date_debut')
        &&
        $request->input('date_debut') != ''
    ) {

        $query->where(
            'date_debut',
            '>=',
            $request->input('date_debut')
        );
    }


    /*
    |--------------------------------------------------------------------------
    | DATE DE FIN
    |--------------------------------------------------------------------------
    */

    if (
        $request->has('date_fin')
        &&
        $request->input('date_fin') != ''
    ) {

        $query->where(
            'date_fin',
            '<=',
            $request->input('date_fin')
        );
    }


    /*
    |--------------------------------------------------------------------------
    | RECUPERATION
    |--------------------------------------------------------------------------
    */

    $pvs = $query
        ->orderBy(
            'annee_academique',
            'desc'
        )
        ->orderBy(
            'semestre',
            'asc'
        )
        ->orderBy(
            'date_generation',
            'desc'
        )
        ->get();


    /*
    |--------------------------------------------------------------------------
    | ANNEES DISPONIBLES
    |--------------------------------------------------------------------------
    */

    $annees = PvGeneration::where(
        'id_classe',
        $id_classe
    )
    ->where(
        'id_cycle',
        $id_cycle
    )
    ->where(
        'id_nniveau',
        $id_nniveau
    )
    ->select('annee_academique')
    ->distinct()
    ->orderBy(
        'annee_academique',
        'desc'
    )
    ->get();


    /*
    |--------------------------------------------------------------------------
    | VUE
    |--------------------------------------------------------------------------
    */

    return view(
        'eleves.pv_historique',
        array(

            'pvs' => $pvs,

            'classe' => $classe,

            'cycle' => $cycle,

            'nniveau' => $nniveau,

            'id_classe' => $id_classe,

            'id_cycle' => $id_cycle,

            'id_nniveau' => $id_nniveau,

            'annees' => $annees

        )
    );
}
public function visualiserPvGeneration($id)
{
    /*
    |--------------------------------------------------------------------------
    | PV
    |--------------------------------------------------------------------------
    */

    $pv = PvGeneration::find($id);


    if (!$pv) {

        abort(
            404,
            'PV introuvable.'
        );
    }


    /*
    |--------------------------------------------------------------------------
    | CONVERSION SEMESTRE -> SEQUENCE
    |--------------------------------------------------------------------------
    */

    $isRattrapage = false;

    if ($pv->semestre == 1) {

        $sequence = 3;

    } elseif ($pv->semestre == 2) {

        $sequence = 4;

    } elseif ($pv->semestre == 9 || $pv->semestre == 'annuel') {

        $sequence = 9;

    } elseif ($pv->semestre == 'rattrapage_1') {

        $sequence = 1;
        $isRattrapage = true;

    } elseif ($pv->semestre == 'rattrapage_2') {

        $sequence = 2;
        $isRattrapage = true;

    } else {

        abort(
            404,
            'Type de PV non reconnu.'
        );
    }


    /*
    |--------------------------------------------------------------------------
    | CONSTRUIRE URL DU PV
    |--------------------------------------------------------------------------
    */

    if ($isRattrapage) {
        $url =
            '/eleves/notes/pv/rattrapages/' .
            $pv->id_classe .

            '?semestre=' .
            $sequence .

            '&cycle=' .
            $pv->id_cycle .

            '&nniveau=' .
            $pv->id_nniveau .

            '&pv_type=' .
            $pv->type_pv;
    } else {
        $url =
            '/eleves/notes/print_note/' .
            $pv->id_classe .

            '?sequence=' .
            $sequence .

            '&cycle=' .
            $pv->id_cycle .

            '&nniveau=' .
            $pv->id_nniveau .

            '&pv_type=' .
            $pv->type_pv;
    }


    /*
    |--------------------------------------------------------------------------
    | PERIODE
    |--------------------------------------------------------------------------
    */

    if ($pv->date_debut) {

        $url .=
            '&date_debut=' .
            $pv->date_debut
                ->format('Y-m-d');
    }


    if ($pv->date_fin) {

        $url .=
            '&date_fin=' .
            $pv->date_fin
                ->format('Y-m-d');
    }


    /*
    |--------------------------------------------------------------------------
    | MODE VISUALISATION HISTORIQUE
    |--------------------------------------------------------------------------
    */

    $url .=
        '&pv_generation_id=' .
        $pv->id;


    /*
    |--------------------------------------------------------------------------
    | REDIRECTION
    |--------------------------------------------------------------------------
    */

    return redirect($url);
}
    public function matiere_show_ancien(Request $request)
    {
         $this->validate($request,[
            "nniveau"=>"required|numeric",
        ]);
        $id=$request->input('id');
        $id_cycle=$request->input('cycle');
        $nniveau=$request->input('nniveau');
        $values= array('titre'=>'Notes');
        $m=DB::select('SELECT m.* FROM matiere m ,classe_matiere cm WHERE m.id=cm.id_matiere AND cm.id_classe=? AND cm.id_cycle=? AND cm.id_nniveau=? ORDER BY m.nom',[$id,$id_cycle,$nniveau]);
        if(session('success')){
            $values['success']=session('success');
            Session::forget('success');
        }
        if(session('erreur')){
            $values['erreur']=session('erreur');
            Session::forget('erreur');
        }
        $values['matieres']=$m;
        $values['id']=$id;
        $values['id_cycle']=$id_cycle;
        $values['id_nniveau']=$nniveau;

        return view('eleves/matiere_note_show',$values);
    }



