        $e = \DB::select(
            'SELECT e.id,e.nom,e.prenom
         FROM eleve e, inscription i
         WHERE i.annee_scolaire = ?
           AND i.id_classe = ?
           AND i.id_eleve = e.id
           AND i.id_cycle = ?
           AND i.id_nniveau = ?
         ORDER BY e.nom, e.prenom',
