        $values['annee_scolaire']  = $annee;
        $values['libelleType']     = $libelleType;
        $values['eleves']          = $e;
        $values['notes']           = $n;
        $values['max']             = $cm->max;
        $values['matiere']         = $mat;
        $values['id_cycle']        = $id_cycle;
        $values['id_classe']       = $id;
        $values['id_nniveau']      = $nniveau;
        $values['sequence']        = $sequence;
        $values['session_exam']    = $sessionExam;
