    private function computeNoteSur20($noteStockee, $pourcentage)
    {
        if ($pourcentage <= 0) return null;
        return $this->normalizeNoteSur20Value(round(($noteStockee * 20) / $pourcentage, 2));
    }

    private function normalizeNoteSur20Value($note)
    {
        if ($note === null || $note === '') {
            return null;
        }

        $note = (float) $note;
        if ($note > 20 && $note <= 100) {
            $note = $note / 5;
        }

        return round($note, 2);
    }

    private function normalizeComponentNoteSur20($note, $pourcentage)
    {
        if ($note === null || $note === '') {
            return null;
        }

        $note = (float) $note;
        if ($note <= 20) {
            return round($note, 2);
        }

        $pourcentage = (float) $pourcentage;
        if ($pourcentage > 0) {
            return $this->normalizeNoteSur20Value(round(($note * 20) / $pourcentage, 2));
        }

        return $this->normalizeNoteSur20Value($note);
    }

