        // ----------------------------------------------------
        $eleves = DB::select("
        SELECT e.id, e.nom, e.prenom, e.matricule
        FROM eleve e
        JOIN inscription i ON i.id_eleve = e.id
        WHERE i.annee_scolaire = ?
        AND i.id_classe = ?
        AND i.id_cycle = ?
        AND i.id_nniveau = ?
