        // ----------------------------------------------------
        $notes = note::where("annee_scolaire", $annee)
            ->where("id_matiere", $id_matiere)
            ->where("sequence", $sequence)
            ->whereIn("id_eleve", $ids_eleves)
            ->get();

        // ----------------------------------------------------
        // 7) CALCUL NOTE BRUTE /20
        // ----------------------------------------------------
        foreach ($notes as $n) {
            if ($pourcentage > 0) {
                $n->brute = round(($n->note * 20) / $pourcentage, 2);
            } else {
                $n->brute = round($n->note, 2);
            }
