    }*/
public function print_note(Request $request, $id_classe)
{
    $this->validate($request, array(
        'sequence' => 'required|numeric',
        'cycle'    => 'required|numeric',
        'nniveau'  => 'required|numeric',
        'pv_type'  => 'sometimes|in:bts,hnd,licence_soa,licence_bamenda,licence_ebolowa,licence_ngaoundere',
        'page_size' => 'sometimes|in:a4,a3'
    ));

    $sequence   = (int) $request->input('sequence');
    $id_matiere = $request->has('id') && $request->input('id') !== '' ? (int) $request->input('id') : null;
    $id_cycle = (int) $request->input('cycle');
    $nniveau  = (int) $request->input('nniveau');
    $annee    = session('year');
    $dateDebut = trim((string) $request->input('date_debut'));
    $dateFin   = trim((string) $request->input('date_fin'));

    if ($dateDebut !== '' && strtotime($dateDebut) === false) abort(400, 'Date de debut invalide.');
    if ($dateFin !== '' && strtotime($dateFin) === false) abort(400, 'Date de fin invalide.');
    if ($dateDebut !== '' && $dateFin !== '' && strtotime($dateFin) < strtotime($dateDebut)) abort(400, 'La date de fin doit etre superieure ou egale a la date de debut.');

    $classeObj  = classe::find($id_classe);
    $cycleObj   = cycle::find($id_cycle);
    $niveauObj  = NNiveau::find($nniveau);
    if (!$classeObj || !$cycleObj || !$niveauObj) abort(404, 'Classe, cycle ou niveau introuvable.');

    if ($id_matiere === null) {
        if ($sequence == 9) {
            $pvType = $this->normalizePvType($request->input('pv_type'), $cycleObj);
            $bilan = $this->buildBilanAnnuelData($id_classe, $id_cycle, $nniveau, $annee, $pvType, $dateDebut, $dateFin);
            $pvContext = $this->buildPvContext($id_classe, $pvType);
            $this->savePvGenerationRecord($classeObj, $cycleObj, $niveauObj, $annee, 'annuel', $pvType, count($bilan['results']), $dateDebut, $dateFin);

            return view('eleves.print_bilan_annuel', array(
                'results' => $bilan['results'],
                'matieres' => $bilan['matieres'],
                'classe' => $classeObj,
                'cycle' => $cycleObj,
                'nniveau' => $niveauObj,
                'id_cycle' => $id_cycle,
                'annee' => $annee,
                'pv_type' => $pvType,
                'campus' => $pvContext['campus'],
                'tutelle' => $pvContext['tutelle'],
                'date_debut' => $dateDebut,
                'date_fin' => $dateFin,
                'titre' => 'Bilan annuel - '.strtoupper($pvType)
            ));
        }

        if ($sequence == 3 || $sequence == 4) {
            $semestre = ($sequence == 3) ? 1 : 2;
            $pvType = $this->normalizePvType($request->input('pv_type'), $cycleObj);
            $bilan = $this->buildBilanAnnuelData($id_classe, $id_cycle, $nniveau, $annee, $pvType, $dateDebut, $dateFin);
            $pvContext = $this->buildPvContext($id_classe, $pvType);
            $matieres = array();
            foreach ($bilan['matieres'] as $m) {
                if (($semestre == 1 && !empty($m->has_note_s1)) || ($semestre == 2 && !empty($m->has_note_s2))) {
                    $m->has_tpe = ($semestre == 1) ? ((float) $m->tpe1 > 0) : ((float) $m->tpe2 > 0);
                    $m->pct_cc = ($semestre == 1) ? $m->cc1 : $m->cc2;
                    $m->pct_sn = ($semestre == 1) ? $m->sn1 : $m->sn2;
                    $m->pct_tpe = ($semestre == 1) ? $m->tpe1 : $m->tpe2;
                    $matieres[] = $m;
                }
            }
            $results = array();
            foreach ($bilan['results'] as $r) {
                $ligne = array('eleve' => $r['eleve'], 'matieres' => array(), 'credit_prevus' => 0, 'credit_valides' => 0, 'moyenne100' => null, 'moyenne20' => $semestre == 1 ? $r['moyenne_s1'] : $r['moyenne_s2'], 'rang' => null, 'decision' => 'R', 'non_valides' => array());
                foreach ($matieres as $m) {
                    $key = isset($m->bilan_key) ? $m->bilan_key : $m->id_matiere;
                    $mm = isset($r['matieres'][$key]['s'.$semestre]) ? $r['matieres'][$key]['s'.$semestre] : null;
                    $ligne['credit_prevus'] += (float) $m->credit;
                    if ($mm && $mm['valide']) $ligne['credit_valides'] += (float) $m->credit;
                    $ligneMatiere = array(
                        'cc' => $mm ? $mm['cc'] : null,
                        'sn' => $mm ? $mm['sn'] : null,
                        'tpe' => $mm ? $mm['tpe'] : null,
                        'cc20' => $mm && isset($mm['cc20']) ? $mm['cc20'] : null,
                        'sn20' => $mm && isset($mm['sn20']) ? $mm['sn20'] : null,
                        'tpe20' => $mm && isset($mm['tpe20']) ? $mm['tpe20'] : null,
                        'has_tpe' => $m->has_tpe,
                        'pct_cc' => (float) $m->pct_cc,
                        'pct_sn' => (float) $m->pct_sn,
                        'pct_tpe' => (float) $m->pct_tpe,
                        'total100' => $mm ? $mm['total100'] : 0,
                        'note20' => $mm ? $mm['note20'] : 0,
                        'credit' => (float) $m->credit,
                        'credit_valide' => ($mm && $mm['valide']) ? (float) $m->credit : 0,
                        'valide' => ($mm && $mm['valide']) ? true : false
                    );
                    $ligne['matieres'][$m->id_matiere] = $ligneMatiere;
                    $ligne['matieres'][$key] = $ligneMatiere;
                }
                $ligne['moyenne100'] = $ligne['moyenne20'] !== null ? round($ligne['moyenne20'] * 5, 2) : null;
                $ligne['decision'] = ($ligne['credit_prevus'] > 0 && $ligne['credit_valides'] >= $ligne['credit_prevus']) ? 'V' : 'R';
                $results[] = $ligne;
            }
            usort($results, function ($a, $b) {
                $ma = $a['moyenne20'] === null ? -1 : $a['moyenne20'];
                $mb = $b['moyenne20'] === null ? -1 : $b['moyenne20'];
                if ($ma == $mb) return 0;
                return ($ma < $mb) ? 1 : -1;
            });

            $rang = 0; $position = 0; $precedente = null;
            foreach ($results as $k => $r) {
                $position++;
                $moy = $r['moyenne20'];
                if ($moy === null) continue;
                if ($precedente === null || $moy < $precedente) $rang = $position;
                $results[$k]['rang'] = $rang;
                $precedente = $moy;
            }
            $this->sortPvResultsByStudentName($results);

            $this->savePvGenerationRecord($classeObj, $cycleObj, $niveauObj, $annee, $semestre, $pvType, count($results), $dateDebut, $dateFin);
            return view('eleves.print_pv', array_merge(array('results' => $results, 'eleves' => $bilan['eleves'], 'matieres' => $matieres, 'classe' => $classeObj, 'cycle' => $cycleObj, 'nniveau' => $niveauObj, 'id_cycle' => $id_cycle, 'annee' => $annee, 'semestre' => $semestre, 'pv_type' => $pvType, 'total_credits' => 0, 'date_debut' => $dateDebut, 'date_fin' => $dateFin, 'titre' => 'PV '.$pvType.' - Semestre '.$semestre), $pvContext));
        }
    }

