private function normalizePvType($pvType, $cycleObj = null)
{
    $pvType = strtolower((string) $pvType);
    if (in_array($pvType, array('bts', 'hnd', 'licence_soa', 'licence_bamenda', 'licence_ebolowa', 'licence_ngaoundere'))) {
        return $pvType;
    }

    $nomCycle = strtoupper($cycleObj && isset($cycleObj->nom) ? $cycleObj->nom : '');
    if (strpos($nomCycle, 'LICENCE') !== false || strpos($nomCycle, 'BACHELOR') !== false) {
        return 'licence_soa';
    }

    return (strpos($nomCycle, 'HND') !== false) ? 'hnd' : 'bts';
}

private function buildPvContext($idClasse, $pvType)
{
    return array(
        'campus' => $this->currentCampus(),
        'tutelle' => $this->resolvePvTutelle($idClasse, $pvType)
    );
}

private function resolvePvTutelle($idClasse, $pvType)
{
    $tutelles = TutelleAcademique::whereHas('specialites', function ($query) use ($idClasse) {
        $query->where('classe.id', '=', $idClasse);
    })->get();

    $pvTypeLower = strtolower((string) $pvType);
    $keywords = array();
    if ($pvTypeLower == 'licence_soa') {
        $keywords = array('YAOUNDE', 'SOA');
    } elseif ($pvTypeLower == 'licence_bamenda' || $pvTypeLower == 'hnd') {
        $keywords = array('BAMENDA');
    } elseif ($pvTypeLower == 'licence_ebolowa') {
        $keywords = array('EBOLOWA', 'ISABEE');
    } elseif ($pvTypeLower == 'licence_ngaoundere') {
        $keywords = array('NGAOUNDERE', 'NGAOUND');
    }

    if (count($keywords) > 0) {
        foreach ($tutelles as $tutelle) {
            $haystack = strtoupper(
                (isset($tutelle->nom) ? $tutelle->nom : '').' '.
                (isset($tutelle->tutelle_anglophone) ? $tutelle->tutelle_anglophone : '').' '.
                (isset($tutelle->ville) ? $tutelle->ville : '').' '.
                (isset($tutelle->localisation) ? $tutelle->localisation : '')
            );
            foreach ($keywords as $keyword) {
                if (strpos($haystack, $keyword) !== false) {
                    return $tutelle;
                }
            }
        }

        $fallbackQuery = TutelleAcademique::where(function ($query) use ($keywords) {
            foreach ($keywords as $keyword) {
                $query->orWhere('nom', 'LIKE', '%'.$keyword.'%')
                    ->orWhere('tutelle_anglophone', 'LIKE', '%'.$keyword.'%')
                    ->orWhere('ville', 'LIKE', '%'.$keyword.'%')
                    ->orWhere('localisation', 'LIKE', '%'.$keyword.'%');
            }
        });
        $fallback = $fallbackQuery->first();
        if ($fallback) {
            return $fallback;
        }
    }

    return count($tutelles) > 0 ? $tutelles->first() : null;
}

private function sortPvResultsByStudentName(&$results)
{
    $self = $this;
    usort($results, function ($a, $b) use ($self) {
        return strcmp($self->pvStudentSortKey($a), $self->pvStudentSortKey($b));
    });
}

private function pvStudentSortKey($row)
{
    $eleve = isset($row['eleve']) ? $row['eleve'] : null;
    $nom = $eleve && isset($eleve->nom) ? $eleve->nom : '';
    $prenom = $eleve && isset($eleve->prenom) ? $eleve->prenom : '';
    $matricule = $eleve && isset($eleve->matricule) ? $eleve->matricule : '';
    $key = strtoupper(trim($nom.' '.$prenom.' '.$matricule));

    return preg_replace('/\s+/', ' ', $key);
}

private function savePvGenerationRecord($classeObj, $cycleObj, $niveauObj, $annee, $semestre, $pvType, $nombreEtudiants, $dateDebut = '', $dateFin = '')
{
    try {
        $nomClasse = preg_replace('/[^A-Za-z0-9_-]/', '_', isset($classeObj->nom) ? $classeObj->nom : 'classe');
        $nomFichier = 'PV_'.strtoupper($pvType).'_'.$semestre.'_'.$nomClasse.'_'.date('Ymd_His').'.html';

        DB::table('pv_generations')->insert(array(
            'id_classe' => $classeObj->id,
            'id_cycle' => $cycleObj->id,
            'id_nniveau' => $niveauObj->id,
            'annee_academique' => $annee,
            'semestre' => (string) $semestre,
            'type_pv' => $pvType,
            'date_debut' => $dateDebut !== '' ? $dateDebut : null,
            'date_fin' => $dateFin !== '' ? $dateFin : null,
            'date_generation' => date('Y-m-d H:i:s'),
            'nombre_etudiants' => $nombreEtudiants,
            'nom_fichier' => $nomFichier,
            'id_user' => Auth::check() ? Auth::id() : null,
            'statut' => 'genere',
            'created_at' => date('Y-m-d H:i:s'),
            'updated_at' => date('Y-m-d H:i:s')
        ));
    } catch (\Exception $e) {
        Log::error('PV generation record failed', array('message' => $e->getMessage()));
        throw $e;
    }
}
private function buildBilanAnnuelData($id_classe, $id_cycle, $nniveau, $annee, $pvType, $dateDebut = '', $dateFin = '')
{
    $campusId = $this->currentCampusId();
    $sqlEleves = "SELECT e.id, e.nom, e.prenom, e.matricule
         FROM eleve e
         JOIN inscription i ON i.id_eleve = e.id
         WHERE i.annee_scolaire = ?
           AND i.id_classe = ?
           AND i.id_cycle = ?
           AND i.id_nniveau = ?";
    $paramsEleves = array($annee, $id_classe, $id_cycle, $nniveau);
    if ($campusId) {
        $sqlEleves .= " AND (i.id_campus = ? OR i.id_campus IS NULL)";
        $paramsEleves[] = $campusId;
    }
    $sqlEleves .= " ORDER BY e.nom, e.prenom";

    $eleves = DB::select($sqlEleves, $paramsEleves);

    $idsEleves = array();
    foreach ($eleves as $e) $idsEleves[] = $e->id;

    $matieres = DB::table('classe_matiere as cm')
        ->join('matiere as m', 'm.id', '=', 'cm.id_matiere')
        ->leftJoin('codages as code_m', DB::raw('code_m.id::text'), '=', 'cm.id_code')
        ->leftJoin('groupe_matieres as gm', function ($join) use ($id_classe, $nniveau) {
            $join->on('gm.id_classe_matiere', '=', 'cm.id')
                 ->where('gm.id_classe', '=', $id_classe)
                 ->where('gm.id_nniveau', '=', $nniveau);
        })
        ->leftJoin('matiere as module_m', 'module_m.id', '=', 'gm.id_matiere_mere')
        ->leftJoin('classe_matiere as module_cm', function ($join) use ($id_classe, $id_cycle, $nniveau) {
            $join->on('module_cm.id_matiere', '=', 'module_m.id')
                 ->where('module_cm.id_classe', '=', $id_classe)
                 ->where('module_cm.id_cycle', '=', $id_cycle)
                 ->where('module_cm.id_nniveau', '=', $nniveau);
        })
        ->leftJoin('codages as code_module', DB::raw('code_module.id::text'), '=', 'module_cm.id_code')
        ->leftJoin('session_exams as se', function ($join) use ($annee) {
            $join->on('se.id_classe_matiere', '=', 'cm.id')
                 ->where('se.annee_academique', '=', $annee);
        })
        ->where('cm.id_classe', $id_classe)
        ->where('cm.id_cycle', $id_cycle)
        ->where('cm.id_nniveau', $nniveau)
        ->select(
            DB::raw('COALESCE(se.id, 0) as id_session'),
            'm.id as id_matiere',
            'm.nom',
            'm.nom_anglais',
            'cm.id as id_classe_matiere',
            'cm.id_code',
            DB::raw("COALESCE(code_m.nom, cm.id_code, '') as code_matiere"),
            'cm.semestre as semestre_programme',
            'cm.coef as credit',
            DB::raw('COALESCE(gm.id_matiere_mere, 0) as id_module'),
            DB::raw('COALESCE(module_m.nom, m.nom) as module_nom'),
            DB::raw('COALESCE(module_m.nom_anglais, m.nom_anglais) as module_nom_anglais'),
            DB::raw("COALESCE(code_module.nom, module_cm.id_code, code_m.nom, cm.id_code, '') as code_module"),
            DB::raw('COALESCE(se.cc1, 0) as cc1'),
            DB::raw('COALESCE(se.sn1, 0) as sn1'),
            DB::raw('COALESCE(se.tpe1, 0) as tpe1'),
            DB::raw('COALESCE(se.ratrappage1, 0) as ratrappage1'),
            DB::raw('COALESCE(se.cc2, 0) as cc2'),
            DB::raw('COALESCE(se.sn2, 0) as sn2'),
            DB::raw('COALESCE(se.tpe2, 0) as tpe2'),
            DB::raw('COALESCE(se.ratrappage2, 0) as ratrappage2')
        )
        ->orderBy('cm.semestre')
        ->orderBy('m.nom')
        ->get();

    foreach ($matieres as $m) {
        $m->bilan_key = (int) $m->id_classe_matiere;
        $semestreProgramme = (int) $m->semestre_programme;
        $hasS1Session = ((float) $m->cc1 > 0 || (float) $m->sn1 > 0 || (float) $m->tpe1 > 0 || (float) $m->ratrappage1 > 0);
        $hasS2Session = ((float) $m->cc2 > 0 || (float) $m->sn2 > 0 || (float) $m->tpe2 > 0 || (float) $m->ratrappage2 > 0);

        if ($semestreProgramme == 0) {
            $m->has_s1 = true;
            $m->has_s2 = true;
        } else {
            $m->has_s1 = $hasS1Session || (!$hasS2Session && $semestreProgramme == 1);
            $m->has_s2 = $hasS2Session || (!$hasS1Session && $semestreProgramme == 2);

            if (!$m->has_s1 && !$m->has_s2) {
                if ($semestreProgramme == 2) $m->has_s2 = true;
                else $m->has_s1 = true;
            }
        }
    }

    $sessionIds = array();
    $matiereIds = array();
    foreach ($matieres as $m) {
        if ((int) $m->id_session > 0) $sessionIds[] = (int) $m->id_session;
        $matiereIds[] = (int) $m->id_matiere;
    }
    $sessionIds = array_values(array_unique($sessionIds));
    $matiereIds = array_values(array_unique($matiereIds));

    $notesMap = array();
    $notesMatiereMap = array();
    $sessionHasSequence = array();
    $matiereHasSequence = array();
    if (count($idsEleves) > 0 && (count($sessionIds) > 0 || count($matiereIds) > 0)) {
        $notesQuery = note::where('annee_scolaire', $annee)
            ->whereIn('id_eleve', $idsEleves)
            ->whereIn('sequence', array(1, 2, 3, 4, 5, 6, 7, 8))
            ->where(function ($q) use ($sessionIds, $matiereIds) {
                if (count($sessionIds) > 0) $q->whereIn('id_session', $sessionIds);
                if (count($matiereIds) > 0) $q->orWhereIn('id_matiere', $matiereIds);
            });

        if ($dateDebut !== '') $notesQuery->where('updated_at', '>=', $dateDebut.' 00:00:00');
        if ($dateFin !== '') $notesQuery->where('updated_at', '<=', $dateFin.' 23:59:59');

        foreach ($notesQuery->get() as $n) {
            $noteValue = round((float) $n->note, 2);
            if ((int) $n->id_session > 0) {
                $notesMap[$n->id_eleve][$n->id_session][$n->sequence] = $noteValue;
                $sessionHasSequence[$n->id_session][$n->sequence] = true;
            }
            $notesMatiereMap[$n->id_eleve][$n->id_matiere][$n->sequence] = $noteValue;
            $matiereHasSequence[$n->id_matiere][$n->sequence] = true;
        }
    }

    foreach ($matieres as $m) {
        $m->has_note_s1 = isset($sessionHasSequence[$m->id_session][3]) || isset($matiereHasSequence[$m->id_matiere][3]) || isset($sessionHasSequence[$m->id_session][5]) || isset($matiereHasSequence[$m->id_matiere][5]);
        $m->has_note_s2 = isset($sessionHasSequence[$m->id_session][4]) || isset($matiereHasSequence[$m->id_matiere][4]) || isset($sessionHasSequence[$m->id_session][6]) || isset($matiereHasSequence[$m->id_matiere][6]);
        if ($m->has_note_s1) $m->has_s1 = true;
        if ($m->has_note_s2) $m->has_s2 = true;
    }

    $results = array();
    foreach ($eleves as $eleve) {
        $ligne = array('eleve' => $eleve, 'matieres' => array(), 'moyenne_s1' => null, 'moyenne_s2' => null, 'moyenne_annuelle' => null, 'credits_s1' => 0, 'credits_s2' => 0, 'credits_valides' => 0, 'credits_prevus' => 0, 'decision' => 'ECHOUE', 'non_valides' => array(), 'rang' => null);
        $sommeS1 = 0; $creditsMoyS1 = 0; $sommeS2 = 0; $creditsMoyS2 = 0;

        foreach ($matieres as $m) {
            $credit = (float) $m->credit;
            $ligne['credits_prevus'] += $credit;
            $matiereValidee = true;
            $matiereConfiguree = false;
            $key = isset($m->bilan_key) ? $m->bilan_key : $m->id_matiere;

            foreach (array(1, 2) as $semestre) {
                if (($semestre == 1 && !$m->has_s1) || ($semestre == 2 && !$m->has_s2)) continue;

                $matiereConfiguree = true;
                $seqCC = ($semestre == 1) ? 1 : 2;
                $seqSN = ($semestre == 1) ? 3 : 4;
                $seqRAT = ($semestre == 1) ? 5 : 6;
                $seqTPE = ($semestre == 1) ? 7 : 8;
                $pctCC = ($semestre == 1) ? (float) $m->cc1 : (float) $m->cc2;
                $pctSN = ($semestre == 1) ? (float) $m->sn1 : (float) $m->sn2;
                $pctRAT = ($semestre == 1) ? (float) $m->ratrappage1 : (float) $m->ratrappage2;
                $pctTPE = ($semestre == 1) ? (float) $m->tpe1 : (float) $m->tpe2;

                $cc = isset($notesMap[$eleve->id][$m->id_session][$seqCC]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqCC] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqCC]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqCC] : null);
                $sn = isset($notesMap[$eleve->id][$m->id_session][$seqSN]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqSN] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqSN]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqSN] : null);
                $rat = isset($notesMap[$eleve->id][$m->id_session][$seqRAT]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqRAT] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqRAT]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqRAT] : null);
                $tpe = isset($notesMap[$eleve->id][$m->id_session][$seqTPE]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqTPE] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqTPE]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqTPE] : null);
                $cc20 = $this->normalizeComponentNoteSur20($cc, $pctCC);
                $sn20 = $this->normalizeComponentNoteSur20($sn, $pctSN);
                $tpe20 = $this->normalizeComponentNoteSur20($tpe, $pctTPE);
                $rat20 = $this->normalizeComponentNoteSur20($rat, $pctRAT);
                $noPercentages = ($pctCC <= 0 && $pctSN <= 0 && $pctTPE <= 0 && $pctRAT <= 0);
                if ($noPercentages) {
                    $cc20 = $cc !== null ? round($cc, 2) : null;
                    $sn20 = $sn !== null ? round($sn, 2) : null;
                    $tpe20 = $tpe !== null ? round($tpe, 2) : null;
                    $rat20 = $rat !== null ? round($rat, 2) : null;
                }

                $cc20 = $this->normalizeNoteSur20Value($cc20);
                $sn20 = $this->normalizeNoteSur20Value($sn20);
                $tpe20 = $this->normalizeNoteSur20Value($tpe20);
                $rat20 = $this->normalizeNoteSur20Value($rat20);
                $normal20 = 0;
                if ($noPercentages) {
                    $rawSum = 0; $rawCount = 0;
                    if ($cc20 !== null) { $rawSum += $cc20; $rawCount++; }
                    if ($sn20 !== null) { $rawSum += $sn20; $rawCount++; }
                    if ($tpe20 !== null) { $rawSum += $tpe20; $rawCount++; }
                    $normal20 = $rawCount > 0 ? round($rawSum / $rawCount, 2) : 0;
                } else {
                    if ($pctCC > 0) $normal20 += ($cc20 !== null ? $cc20 : 0) * ($pctCC / 100);
                    if ($pctSN > 0) $normal20 += ($sn20 !== null ? $sn20 : 0) * ($pctSN / 100);
                    if ($pctTPE > 0) $normal20 += ($tpe20 !== null ? $tpe20 : 0) * ($pctTPE / 100);
                }
                $normal20 = $this->normalizeNoteSur20Value(round($normal20, 2));
                $normal100 = round($normal20 * 5, 2);

                $final100 = $normal100;
                $sessionValidation = ($normal100 >= 50) ? 'Session normale' : 'Non validee';
                if ((int) $m->id_session <= 0) $sessionValidation = 'Session non configuree';

                if ($rat !== null && ($pctRAT > 0 || $noPercentages)) {
                    $rattrapage20 = 0;
                    if ($noPercentages) {
                        $rattrapage20 = $rat20 !== null ? $rat20 : 0;
                    } else {
                        if ($pctCC > 0) $rattrapage20 += ($cc20 !== null ? $cc20 : 0) * ($pctCC / 100);
                        $rattrapage20 += ($rat20 !== null ? $rat20 : 0) * ($pctRAT / 100);
                        if ($pctTPE > 0) $rattrapage20 += ($tpe20 !== null ? $tpe20 : 0) * ($pctTPE / 100);
                    }
                    $rattrapage20 = $this->normalizeNoteSur20Value(round($rattrapage20, 2));
                    $rattrapage100 = round($rattrapage20 * 5, 2);
                    if ($rattrapage100 > $final100) $final100 = $rattrapage100;
                    if ($final100 >= 50) $sessionValidation = 'Rattrapage';
                }

                $valide = ($final100 >= 50);
                if (!$valide) {
                    $matiereValidee = false;
                    $ligne['non_valides'][] = $m->nom.' S'.$semestre;
                } else {
                    if ($semestre == 1) $ligne['credits_s1'] += $credit;
                    if ($semestre == 2) $ligne['credits_s2'] += $credit;
                }

                $final20 = $this->normalizeNoteSur20Value(round($final100 / 5, 2));
                $final100 = round($final20 * 5, 2);
                if ($semestre == 1 && !empty($m->has_note_s1)) { $sommeS1 += ($final20 * $credit); $creditsMoyS1 += $credit; }
                if ($semestre == 2 && !empty($m->has_note_s2)) { $sommeS2 += ($final20 * $credit); $creditsMoyS2 += $credit; }
                $ligne['matieres'][$key]['s'.$semestre] = array('cc' => $cc, 'sn' => $sn, 'rat' => $rat, 'tpe' => $tpe, 'cc20' => $cc20, 'sn20' => $sn20, 'rat20' => $rat20, 'tpe20' => $tpe20, 'total100' => $final100, 'note20' => $final20, 'credit' => $credit, 'valide' => $valide, 'session_validation' => $sessionValidation);
            }

            if (!$matiereConfiguree) {
                $matiereValidee = false;
                $ligne['non_valides'][] = $m->nom;
            }
            if ($matiereValidee && $matiereConfiguree) $ligne['credits_valides'] += $credit;
        }

        $ligne['moyenne_s1'] = $creditsMoyS1 > 0 ? round($sommeS1 / $creditsMoyS1, 2) : null;
        $ligne['moyenne_s2'] = $creditsMoyS2 > 0 ? round($sommeS2 / $creditsMoyS2, 2) : null;
        $moyenneS1PourAnnuel = $ligne['moyenne_s1'] !== null ? $ligne['moyenne_s1'] : 0;
        $moyenneS2PourAnnuel = $ligne['moyenne_s2'] !== null ? $ligne['moyenne_s2'] : 0;
        $ligne['moyenne_annuelle'] = round(($moyenneS1PourAnnuel + $moyenneS2PourAnnuel) / 2, 2);
        $ligne['decision'] = ($ligne['credits_prevus'] > 0 && $ligne['credits_valides'] >= $ligne['credits_prevus']) ? 'ADMIS' : 'ECHOUE';
        $results[] = $ligne;
    }

    usort($results, function ($a, $b) {
        $ma = $a['moyenne_annuelle'] === null ? -1 : $a['moyenne_annuelle'];
        $mb = $b['moyenne_annuelle'] === null ? -1 : $b['moyenne_annuelle'];
        if ($ma == $mb) return 0;
        return ($ma < $mb) ? 1 : -1;
    });

    $rang = 0; $position = 0; $precedente = null;
    foreach ($results as $k => $r) {
        $position++;
        $moy = $r['moyenne_annuelle'];
        if ($moy === null) continue;
        if ($precedente === null || $moy < $precedente) $rang = $position;
        $results[$k]['rang'] = $rang;
        $precedente = $moy;
    }
    $this->sortPvResultsByStudentName($results);

    return array('eleves' => $eleves, 'matieres' => $matieres, 'results' => $results);
}

public function listeRattrapagesSessionExams(Request $request, $id_classe)
{
    $this->validate($request, array(
        'semestre' => 'required|numeric',
        'cycle'    => 'required|numeric',
        'nniveau'  => 'required|numeric',
        'pv_type'  => 'sometimes|in:bts,hnd,licence_soa,licence_bamenda,licence_ebolowa,licence_ngaoundere',
        'page_size' => 'sometimes|in:a4,a3',
        'global' => 'sometimes|in:0,1',
        'only_done' => 'sometimes|in:0,1'
    ));

    $semestre = (int) $request->input('semestre');
    if ($semestre !== 1 && $semestre !== 2) {
        abort(404, 'Semestre inconnu.');
    }

    $id_cycle = (int) $request->input('cycle');
    $nniveau = (int) $request->input('nniveau');
    $annee = session('year');
    $campusId = $this->currentCampusId();
    $pageSize = strtolower((string) $request->input('page_size'));
    if ($pageSize !== 'a3') {
        $pageSize = 'a4';
    }
    $globalMode = $request->input('global') == '1';
    $onlyDone = $request->input('only_done') == '1';

    $dateDebut = trim((string) $request->input('date_debut'));
    $dateFin = trim((string) $request->input('date_fin'));
    if ($dateDebut !== '' && strtotime($dateDebut) === false) {
        abort(400, 'Date de debut invalide.');
    }
    if ($dateFin !== '' && strtotime($dateFin) === false) {
        abort(400, 'Date de fin invalide.');
    }
    if ($dateDebut !== '' && $dateFin !== '' && strtotime($dateFin) < strtotime($dateDebut)) {
        abort(400, 'La date de fin doit etre superieure ou egale a la date de debut.');
    }

    $classeObj = classe::find($id_classe);
    $cycleObj = cycle::find($id_cycle);
    $niveauObj = NNiveau::find($nniveau);

    if (!$classeObj || !$cycleObj || !$niveauObj) {
        abort(404, 'Classe, cycle ou niveau introuvable.');
    }

    $pvType = $this->normalizePvType($request->input('pv_type'), $cycleObj);

    $seqCC = ($semestre == 1) ? 1 : 2;
    $seqSN = ($semestre == 1) ? 3 : 4;
    $seqRAT = ($semestre == 1) ? 5 : 6;
    $seqTPE = ($semestre == 1) ? 7 : 8;

    $champCC = ($semestre == 1) ? 'cc1' : 'cc2';
    $champSN = ($semestre == 1) ? 'sn1' : 'sn2';
    $champRAT = ($semestre == 1) ? 'ratrappage1' : 'ratrappage2';
    $champTPE = ($semestre == 1) ? 'tpe1' : 'tpe2';

    $sqlEleves = "SELECT e.id, e.nom, e.prenom, e.matricule
         FROM eleve e
         JOIN inscription i ON i.id_eleve = e.id
         WHERE i.annee_scolaire = ?
           AND i.id_classe = ?
           AND i.id_cycle = ?
           AND i.id_nniveau = ?";
    $paramsEleves = array($annee, $id_classe, $id_cycle, $nniveau);
    if ($campusId) {
        $sqlEleves .= " AND (i.id_campus = ? OR i.id_campus IS NULL)";
        $paramsEleves[] = $campusId;
    }
    $sqlEleves .= " ORDER BY e.nom, e.prenom";

    $eleves = DB::select($sqlEleves, $paramsEleves);

    $idsEleves = array();
    foreach ($eleves as $e) {
        $idsEleves[] = $e->id;
    }

    $matieres = DB::table('classe_matiere as cm')
        ->leftJoin('session_exams as se', function ($join) use ($annee) {
            $join->on('se.id_classe_matiere', '=', 'cm.id')
                 ->where('se.annee_academique', '=', $annee);
        })
        ->join('matiere as m', 'm.id', '=', 'cm.id_matiere')
        ->leftJoin('codages as code_m', DB::raw('code_m.id::text'), '=', 'cm.id_code')
        ->where('cm.id_classe', $id_classe)
        ->where('cm.id_cycle', $id_cycle)
        ->where('cm.id_nniveau', $nniveau)
        ->where(function ($q) use ($champCC, $champSN, $champRAT, $champTPE, $semestre) {
            $q->where('se.'.$champCC, '>', 0)
              ->orWhere('se.'.$champSN, '>', 0)
              ->orWhere('se.'.$champRAT, '>', 0)
              ->orWhere('se.'.$champTPE, '>', 0)
              ->orWhere('cm.semestre', '=', $semestre);
        })
        ->select(
            DB::raw('COALESCE(se.id, 0) as id_session'),
            'm.id as id_matiere',
            'm.nom',
            'm.nom_anglais',
            'cm.id as id_classe_matiere',
            'cm.id_code',
            DB::raw("COALESCE(cm.id_code, code_m.nom, '') as code_matiere"),
            'cm.coef as credit',
            DB::raw('COALESCE(se.'.$champCC.', 0) as pct_cc'),
            DB::raw('COALESCE(se.'.$champSN.', 0) as pct_sn'),
            DB::raw('COALESCE(se.'.$champRAT.', 0) as pct_rat'),
            DB::raw('COALESCE(se.'.$champTPE.', 0) as pct_tpe')
        )
        ->orderBy('cm.semestre')
        ->orderBy('m.nom')
        ->get();

    $sessionIds = array();
    $matiereIds = array();
    foreach ($matieres as $m) {
        if ((int) $m->id_session > 0) $sessionIds[] = (int) $m->id_session;
        $matiereIds[] = (int) $m->id_matiere;
    }
    $sessionIds = array_values(array_unique($sessionIds));
    $matiereIds = array_values(array_unique($matiereIds));

    $notesMap = array();
    $notesMatiereMap = array();
    if ((count($sessionIds) > 0 || count($matiereIds) > 0) && count($idsEleves) > 0) {
        $notesQuery = note::where('annee_scolaire', $annee)
            ->whereIn('id_eleve', $idsEleves)
            ->whereIn('sequence', array($seqCC, $seqSN, $seqRAT, $seqTPE))
            ->where(function ($q) use ($sessionIds, $matiereIds) {
                if (count($sessionIds) > 0) $q->whereIn('id_session', $sessionIds);
                if (count($matiereIds) > 0) $q->orWhereIn('id_matiere', $matiereIds);
            });

        if ($dateDebut !== '') {
            $notesQuery->where('updated_at', '>=', $dateDebut.' 00:00:00');
        }
        if ($dateFin !== '') {
            $notesQuery->where('updated_at', '<=', $dateFin.' 23:59:59');
        }

        $notes = $notesQuery->get();
        foreach ($notes as $n) {
            if ((int) $n->id_session > 0) {
                $notesMap[$n->id_eleve][$n->id_session][$n->sequence] = round((float) $n->note, 2);
            }
            $notesMatiereMap[$n->id_eleve][$n->id_matiere][$n->sequence] = round((float) $n->note, 2);
        }
    }

    $results = array();
    foreach ($eleves as $eleve) {
        $nonValides = array();
        foreach ($matieres as $m) {
            $cc = isset($notesMap[$eleve->id][$m->id_session][$seqCC]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqCC] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqCC]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqCC] : null);
            $sn = isset($notesMap[$eleve->id][$m->id_session][$seqSN]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqSN] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqSN]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqSN] : null);
            $rat = isset($notesMap[$eleve->id][$m->id_session][$seqRAT]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqRAT] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqRAT]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqRAT] : null);
            $tpe = isset($notesMap[$eleve->id][$m->id_session][$seqTPE]) ? (float) $notesMap[$eleve->id][$m->id_session][$seqTPE] : (isset($notesMatiereMap[$eleve->id][$m->id_matiere][$seqTPE]) ? (float) $notesMatiereMap[$eleve->id][$m->id_matiere][$seqTPE] : null);

            $normal100 = 0;
            if ((float) $m->pct_cc <= 0 && (float) $m->pct_sn <= 0 && (float) $m->pct_tpe <= 0) {
                $rawSum = 0; $rawCount = 0;
                if ($cc !== null) { $rawSum += $cc; $rawCount++; }
                if ($sn !== null) { $rawSum += $sn; $rawCount++; }
                if ($tpe !== null) { $rawSum += $tpe; $rawCount++; }
                $normal100 = $rawCount > 0 ? round(($rawSum / $rawCount) * 5, 2) : 0;
            } else {
                if ((float) $m->pct_cc > 0) $normal100 += ($cc !== null ? $cc : 0);
                if ((float) $m->pct_sn > 0) $normal100 += ($sn !== null ? $sn : 0);
                if ((float) $m->pct_tpe > 0) $normal100 += ($tpe !== null ? $tpe : 0);
            }
            $normal100 = round($normal100, 2);

            $total100 = $normal100;
            $rattrapage100 = null;
            if ($rat !== null) {
                if ((float) $m->pct_rat > 0) {
                    $rattrapage100 = 0;
                    if ((float) $m->pct_cc > 0) $rattrapage100 += ($cc !== null ? $cc : 0);
                    $rattrapage100 += $rat;
                    if ((float) $m->pct_tpe > 0) $rattrapage100 += ($tpe !== null ? $tpe : 0);
                } else {
                    $rattrapage100 = $rat * 5;
                }
                $rattrapage100 = round($rattrapage100, 2);
                if ($rattrapage100 > $total100) {
                    $total100 = $rattrapage100;
                }
            }

            $mustList = $onlyDone ? ($rat !== null) : ($normal100 < 50 || $rat !== null);
            if ($mustList) {
                $nonValides[] = array(
                    'matiere' => $m,
                    'cc' => $cc,
                    'sn' => $sn,
                    'rat' => $rat,
                    'tpe' => $tpe,
                    'normal100' => $normal100,
                    'normal20' => round($normal100 / 5, 2),
                    'rattrapage100' => $rattrapage100,
                    'rattrapage20' => $rattrapage100 !== null ? round($rattrapage100 / 5, 2) : null,
                    'total100' => $total100,
                    'note20' => round($total100 / 5, 2),
                    'credit' => (float) $m->credit,
                    'valide' => ($total100 >= 50),
                    'has_rattrapage' => ($rat !== null)
                );
            }
        }

        if (count($nonValides) > 0 || ($globalMode && !$onlyDone)) {
            $results[] = array(
                'eleve' => $eleve,
                'non_valides' => $nonValides
            );
        }
    }

    $this->savePvGenerationRecord($classeObj, $cycleObj, $niveauObj, $annee, 'rattrapage_'.$semestre, $pvType, count($results), $dateDebut, $dateFin);

    return view('eleves.liste_rattrapages_session_exams', array_merge(array(
        'results' => $results,
        'classe' => $classeObj,
        'cycle' => $cycleObj,
        'nniveau' => $niveauObj,
        'annee' => $annee,
        'semestre' => $semestre,
        'pv_type' => $pvType,
        'date_debut' => $dateDebut,
        'date_fin' => $dateFin,
        'page_size' => $pageSize,
        'global_mode' => $globalMode,
        'only_done' => $onlyDone,
        'matieres' => $matieres,
        'titre' => 'PV rattrapages - Semestre '.$semestre
    ), $this->buildPvContext($id_classe, $pvType)));
}

public function deliberationsEtudiants(Request $request, $id_classe)
{
    $this->validate($request, array(
        'semestre' => 'required|numeric',
        'cycle' => 'required|numeric',
        'nniveau' => 'required|numeric',
        'mode' => 'sometimes|in:semestre,rattrapage',
        'target_note' => 'sometimes|numeric'
    ));

    $semestre = (int) $request->input('semestre');
    if ($semestre !== 1 && $semestre !== 2) abort(404, 'Semestre inconnu.');

    $id_cycle = (int) $request->input('cycle');
    $nniveau = (int) $request->input('nniveau');
    $mode = $request->input('mode') === 'rattrapage' ? 'rattrapage' : 'semestre';
    $targetNote = (float) str_replace(',', '.', (string) $request->input('target_note', 10));
    if ($targetNote < 0) $targetNote = 0;
    if ($targetNote > 20) $targetNote = 20;
    $annee = session('year');

    $classeObj = classe::find($id_classe);
    $cycleObj = cycle::find($id_cycle);
    $niveauObj = NNiveau::find($nniveau);
    if (!$classeObj || !$cycleObj || !$niveauObj) abort(404, 'Classe, cycle ou niveau introuvable.');

    $bilan = $this->buildBilanAnnuelData($id_classe, $id_cycle, $nniveau, $annee, 'bts');

    return view('eleves.deliberations_etudiants', array(
        'results' => $bilan['results'],
        'matieres' => $bilan['matieres'],
        'classe' => $classeObj,
        'cycle' => $cycleObj,
        'nniveau' => $niveauObj,
        'id_cycle' => $id_cycle,
        'semestre' => $semestre,
        'mode' => $mode,
        'target_note' => $targetNote,
        'annee' => $annee,
        'titre' => 'Deliberations par etudiant - Semestre '.$semestre
    ));
}

public function applyDeliberationsEtudiants(Request $request)
{
    $this->validate($request, array(
        'id_classe' => 'required|numeric',
        'cycle' => 'required|numeric',
        'nniveau' => 'required|numeric',
        'semestre' => 'required|numeric',
        'mode' => 'required|in:semestre,rattrapage'
    ));

    $idClasse = (int) $request->input('id_classe');
    $idCycle = (int) $request->input('cycle');
    $idNniveau = (int) $request->input('nniveau');
    $semestre = (int) $request->input('semestre');
    $mode = $request->input('mode');
    $annee = session('year');

    $apply = (array) $request->input('apply');
    $eleves = (array) $request->input('eleve_id');
    $matieres = (array) $request->input('matiere_id');
    $sessions = (array) $request->input('session_id');
    $targets = (array) $request->input('target_note');

    $seqTarget = ($mode === 'rattrapage') ? (($semestre == 1) ? 5 : 6) : (($semestre == 1) ? 3 : 4);
    $seqCC = ($semestre == 1) ? 1 : 2;
    $seqTPE = ($semestre == 1) ? 7 : 8;

    foreach ($apply as $idx => $checked) {
        if (!isset($eleves[$idx]) || !isset($matieres[$idx]) || !isset($sessions[$idx]) || !isset($targets[$idx])) continue;
        if ($targets[$idx] === '') continue;

        $idEleve = (int) $eleves[$idx];
        $idMatiere = (int) $matieres[$idx];
        $idSession = (int) $sessions[$idx];
        $target20 = (float) str_replace(',', '.', $targets[$idx]);
        if ($target20 < 0) $target20 = 0;
        if ($target20 > 20) $target20 = 20;
        $target100 = $target20 * 5;

        $sessionExam = Session_exam::find($idSession);
        if (!$sessionExam) continue;

        $cc = note::where('annee_scolaire', $annee)->where('id_eleve', $idEleve)->where('id_matiere', $idMatiere)->where('id_session', $idSession)->where('sequence', $seqCC)->first();
        $tpe = note::where('annee_scolaire', $annee)->where('id_eleve', $idEleve)->where('id_matiere', $idMatiere)->where('id_session', $idSession)->where('sequence', $seqTPE)->first();

        $base = 0;
        if ($cc) $base += (float) $cc->note;
        if ($tpe) $base += (float) $tpe->note;
        $newContribution = round(max(0, $target100 - $base), 2);

        $note = note::where('annee_scolaire', $annee)->where('id_eleve', $idEleve)->where('id_matiere', $idMatiere)->where('id_session', $idSession)->where('sequence', $seqTarget)->first();
        if (!$note) {
            $note = new note();
            $note->annee_scolaire = $annee;
            $note->id_eleve = $idEleve;
            $note->id_matiere = $idMatiere;
            $note->id_session = $idSession;
            $note->sequence = $seqTarget;
            $note->id_creator = Auth::check() ? Auth::id() : null;
        }
        $note->note = $newContribution;
        $note->id_classe = $idClasse;
        $note->id_classe_matiere = $sessionExam->id_classe_matiere;
        $note->id_last_editor = Auth::check() ? Auth::id() : null;
        $note->edition_details = 'deliberation '.$mode.' vers '.$target20.'/20';
        $note->save();
    }

    session(array('success' => true));
    return redirect()->to('/eleves/notes/deliberations/'.$idClasse.'?semestre='.$semestre.'&cycle='.$idCycle.'&nniveau='.$idNniveau.'&mode='.$mode);
}
