                ->where('cm.id_cycle',  $id_cycle)
                ->where('cm.id_nniveau',$nniveau)
                ->where(function($q){
                    $q->where('se.cc1','>','0')
                        ->orWhere('se.sn1','>','0')
                        ->orWhere('se.tpe1','>','0')
                        ->orWhere('se.ratrappage1','>','0')
                        ->orWhere('cm.semestre', '=', 1);
                })
                ->select('m.*', 'cm.id as id_classe_matiere', 'cm.coef as credit', DB::raw('COALESCE(se.id, 0) as id_session'))
                ->orderBy('m.nom')
                ->get();
        } else {
            $matieres = DB::table('classe_matiere as cm')
                ->leftJoin('session_exams as se', function ($join) use ($annee) {
                    $join->on('se.id_classe_matiere', '=', 'cm.id')
                         ->where('se.annee_academique', '=', $annee);
                })
                ->join('matiere as m', 'm.id', '=', 'cm.id_matiere')
                ->where('cm.id_classe', $classeId)
                ->where('cm.id_cycle',  $id_cycle)
                ->where('cm.id_nniveau',$nniveau)
                ->where(function($q){
                    $q->where('se.cc2','>','0')
                        ->orWhere('se.sn2','>','0')
                        ->orWhere('se.tpe2','>','0')
                        ->orWhere('se.ratrappage2','>','0')
                        ->orWhere('cm.semestre', '=', 2);
                })
                ->select('m.*', 'cm.id as id_classe_matiere', 'cm.coef as credit', DB::raw('COALESCE(se.id, 0) as id_session'))
                ->orderBy('m.nom')
                ->get();
        }

        $nb_matieres = count($matieres);

        // 3) init PV map
        $PV_map = array();
        $sumNote100 = array();
        $sumCoef = array();
        foreach ($eleves as $e) {
            $PV_map[$e->id] = new PVsem($e->id, array(), 0);
            $sumNote100[$e->id] = 0;
            $sumCoef[$e->id] = 0;
        }

