        $eleves = DB::select(
            "SELECT e.* FROM eleve e
         JOIN inscription i ON i.id_eleve = e.id
         WHERE i.annee_scolaire=?
           AND i.id_classe=?
           AND i.id_cycle=?
           AND i.id_nniveau=?
         ORDER BY e.nom, e.prenom",
            array($annee, $classe_id, $id_cycle, $nniveau)
        );

        $elevesIds = array_map(function($e){
            return $e->id;
