        // petit util pour chercher dans une collection / array result
        $findNoteForEleve = function($collection, $id_eleve) {
            foreach ($collection as $n) {
                if (isset($n->id_eleve) && $n->id_eleve == $id_eleve) return $n;
            }
            return null;
        };

