        $eleves = DB::select(
            'SELECT e.*
         FROM eleve e, inscription i
         WHERE i.annee_scolaire = ?
           AND i.id_classe      = ?
           AND i.id_eleve       = e.id
           AND i.id_cycle       = ?
           AND i.id_nniveau     = ?
         ORDER BY e.nom, e.prenom',
            array($annee, $classe_id, $id_cycle, $nniveau)
        );

        $elevesIds = array();
        foreach ($eleves as $e) {
            $elevesIds[] = $e->id;
