    /**
     * Fusionne les modules des deux semestres en module annuel
     */
    private function mergeModulesAnnuel($M1, $M2)
    {
        $res = [];

        // Modules Semestre 1
        foreach ($M1 as $id_mere => $uvList) {
            $res[$id_mere] = $uvList;
        }

        // Modules Semestre 2
        foreach ($M2 as $id_mere => $uvList) {
            if (!isset($res[$id_mere])) {
                $res[$id_mere] = $uvList;
                continue;
            }
