    private function renderRattrapage($eleves, $notes_rat, $matiere, $cm, $id_classe, $id_cycle, $nniveau, $sequence)
    {
        $annee  = session('year');

        // R1 -> CC1 + SN1 + TPE1(7)
        // R2 -> CC2 + SN2 + TPE2(8)
        $seqCC  = ($sequence == 5 ? 1 : 2);
        $seqSN  = ($sequence == 5 ? 3 : 4);
