                    //$matieres[$l]=new pv_matiere($co->id_matiere,$co_note,$s_co_coef);
                    if(!$minus_credit_cpst) {
                        //$liste_mat[$l]=new matiere_groupe($co->id_matiere,$co->nom);
                    }
                    $l++;

