    /**
	 * Store a newly created resource in storage.
	 *
	 * @return Response
	 */
    public function importPage(Request $request)
    {
        $selectedClasse = $request->input('id_classe');
        $selectedCycle = $request->input('id_cycle');
        $selectedNniveau = $request->input('id_nniveau');
        $specialitesCampus = DB::table('campus_specialite')
            ->where('id_campus', '=', $this->currentCampusId())
            ->lists('id_classe');
        $specialitesCampusArray = is_array($specialitesCampus) ? $specialitesCampus : $specialitesCampus->toArray();
        if ($selectedClasse && count($specialitesCampusArray) > 0 && !in_array((int)$selectedClasse, array_map('intval', $specialitesCampusArray))) {
            $selectedClasse = null;
        }

        $classesQuery = classe::with('niveau')->orderBy('nom');
        if (count($specialitesCampusArray) > 0) {
            $classesQuery->whereIn('id', $specialitesCampusArray);
        }

        $programmesQuery = DB::table('classe_matiere as cm')
            ->leftJoin('classe as c', 'c.id', '=', 'cm.id_classe')
            ->leftJoin('matiere as m', 'm.id', '=', 'cm.id_matiere')
            ->leftJoin('cycle as cy', 'cy.id', '=', 'cm.id_cycle')
            ->leftJoin('n_niveaus as nn', 'nn.id', '=', 'cm.id_nniveau')
            ->select('cm.*', 'c.nom as classe_nom', 'm.nom as matiere_nom', 'cy.nom as cycle_nom', 'nn.nom as nniveau_nom')
            ->orderBy('c.nom')
            ->orderBy('m.nom');

        if ($selectedClasse) {
            $programmesQuery->where('cm.id_classe', '=', $selectedClasse);
        } else {
            $programmesQuery->whereRaw('1 = 0');
        }
        if ($selectedCycle) {
            $programmesQuery->where('cm.id_cycle', '=', $selectedCycle);
        }
        if ($selectedNniveau) {
            $programmesQuery->where('cm.id_nniveau', '=', $selectedNniveau);
        }

        $matieresQuery = matiere::orderBy('nom');
        if ($selectedClasse) {
            $matieresQuery->whereIn('id', function ($query) use ($selectedClasse, $selectedCycle, $selectedNniveau) {
                $query->select('id_matiere')
                    ->from('classe_matiere')
                    ->where('id_classe', '=', $selectedClasse);
                if ($selectedCycle) {
                    $query->where('id_cycle', '=', $selectedCycle);
                }
                if ($selectedNniveau) {
                    $query->where('id_nniveau', '=', $selectedNniveau);
                }
            });
        } else {
            $matieresQuery->whereRaw('1 = 0');
        }

        $sessionsQuery = DB::table('session_exams as se')
            ->leftJoin('classe_matiere as cm', 'cm.id', '=', 'se.id_classe_matiere')
            ->leftJoin('classe as c', 'c.id', '=', 'cm.id_classe')
            ->leftJoin('matiere as m', 'm.id', '=', 'se.id_matiere')
            ->select('se.*', 'c.nom as classe_nom', 'm.nom as matiere_nom')
            ->orderBy('c.nom')
            ->orderBy('m.nom');

        if ($selectedClasse) {
            $sessionsQuery->where('cm.id_classe', '=', $selectedClasse);
        } else {
            $sessionsQuery->whereRaw('1 = 0');
        }
        if ($selectedCycle) {
            $sessionsQuery->where('cm.id_cycle', '=', $selectedCycle);
        }
        if ($selectedNniveau) {
            $sessionsQuery->where('cm.id_nniveau', '=', $selectedNniveau);
        }

        $values = array(
            'titre' => 'Importation des notes',
            'fields' => $this->noteImportFields($selectedClasse, $selectedCycle, $selectedNniveau),
            'selected_classe' => $selectedClasse,
            'selected_cycle' => $selectedCycle,
            'selected_nniveau' => $selectedNniveau,
            'selected_classe_model' => $selectedClasse ? classe::find($selectedClasse) : null,
            'campus' => Campus::where('id', '=', $this->currentCampusId())->get(),
            'cycles' => cycle::orderBy('nom')->get(),
            'niveaux' => niveau::orderBy('nom')->get(),
            'classes' => $classesQuery->get(),
            'nniveaux' => NNiveau::orderBy('nom')->get(),
            'matieres' => $matieresQuery->get(),
            'programmes' => $programmesQuery->get(),
            'sessions_examens' => $sessionsQuery->get()
        );

        if (session('import_notes_success')) {
            $values['import_success'] = session('import_notes_success');
            Session::forget('import_notes_success');
        }

        return view('eleves.import_notes', $values);
    }

    public function downloadNoteImportTemplate(Request $request)
    {
        $selectedClasse = $request->input('id_classe', 1);
        $selectedCycle = $request->input('id_cycle', 1);
        $selectedNniveau = $request->input('id_nniveau', 1);
        $headers = array_keys($this->noteImportFields($selectedClasse, $selectedCycle, $selectedNniveau));
        $sample = array(
            '', '25AZ-SIN3563', $this->currentCampusId(), session('year'), $selectedCycle, '', $selectedClasse, $selectedNniveau, 1, '', '', 1, 14.5
        );

        $handle = fopen('php://temp', 'r+');
        fputcsv($handle, $headers, ';');
        fputcsv($handle, $sample, ';');
        rewind($handle);

        return Response::make(stream_get_contents($handle), 200, array(
            'Content-Type' => 'text/csv; charset=UTF-8',
            'Content-Disposition' => 'attachment; filename="template_import_notes.csv"'
        ));
    }

    public function importNotesFromExcel(Request $request)
    {
        $this->validate($request, array(
            'fichier_notes' => 'required'
        ));

        $file = $request->file('fichier_notes');
        if (!$file || !$file->isValid()) {
            return redirect()->back()->withErrors(array('Le fichier des notes est invalide.'));
        }

        try {
            $rows = $this->readNoteImportRows($file);
        } catch (\Exception $e) {
            return redirect()->back()->withErrors(array($e->getMessage()));
        }

        if (count($rows) == 0) {
            return redirect()->back()->withErrors(array('Le fichier ne contient aucune ligne exploitable.'));
        }

        $created = 0;
        $updated = 0;
        $errors = array();
        $noteHasCampus = DB::getSchemaBuilder()->hasColumn('note', 'id_campus');
        $context = array(
            'id_classe' => $request->input('context_id_classe'),
            'id_cycle' => $request->input('context_id_cycle'),
            'id_nniveau' => $request->input('context_id_nniveau')
        );

        foreach ($rows as $line => $row) {
            try {
                $this->applyNoteImportContext($row, $context);
                $result = $this->saveImportedNoteRow($row, $line, $noteHasCampus);
                if ($result == 'created') {
                    $created++;
                } else {
                    $updated++;
                }
            } catch (\Exception $e) {
                $errors[] = 'Ligne '.$line.' : '.$e->getMessage();
            }
        }

        if (count($errors) > 0) {
            return redirect()->back()->withErrors(array(implode(' | ', array_slice($errors, 0, 12))));
        }

        session(array('import_notes_success' => $created.' note(s) creee(s), '.$updated.' note(s) mise(s) a jour.'));
        return redirect()->route('notes_import');
    }

