    private function applyNoteImportContext(&$row, $context)
    {
        foreach (array('id_classe', 'id_cycle', 'id_nniveau') as $key) {
            if (!isset($context[$key]) || trim((string)$context[$key]) === '') {
                continue;
            }
            if ($this->hasImportValue($row, $key) && (int)$row[$key] !== (int)$context[$key]) {
                throw new \Exception($key.' du fichier ne correspond pas a la selection de l interface.');
            }
            $row[$key] = $context[$key];
        }
    }

    private function saveImportedNoteRow($row, $line, $noteHasCampus)
    {
        $campusId = $this->currentCampusId();
        $annee = $this->valueOrDefault($row, 'annee_scolaire', session('year'));
        $rowCampus = $this->valueOrDefault($row, 'id_campus', $campusId);

        if (!$campusId) {
            throw new \Exception('Aucun campus actif.');
        }
        if ((int)$rowCampus !== (int)$campusId) {
            throw new \Exception('Le campus indique ne correspond pas au campus actif.');
        }

        $student = $this->findNoteImportStudent($row);
        $idCycle = $this->requiredImportInt($row, 'id_cycle');
        $idClasse = $this->requiredImportInt($row, 'id_classe');
        $idNniveau = $this->requiredImportInt($row, 'id_nniveau');
        $idMatiere = $this->requiredImportInt($row, 'id_matiere');
        $sequence = $this->requiredImportInt($row, 'sequence');
        $rawNote = $this->requiredImportNumber($row, 'note');

        if ($rawNote < 0 || $rawNote > 20) {
            throw new \Exception('La note doit etre comprise entre 0 et 20.');
        }

        $classe = classe::find($idClasse);
        if (!$classe) {
            throw new \Exception('Specialite introuvable.');
        }
        if ($this->hasImportValue($row, 'id_niveau') && (int)$classe->id_niveau !== (int)$row['id_niveau']) {
            throw new \Exception('La filiere ne correspond pas a la specialite.');
        }
        if (!matiere::find($idMatiere)) {
            throw new \Exception('Matiere introuvable.');
        }

        $inscription = inscription::where('id_eleve', '=', $student->id)
            ->where('annee_scolaire', '=', $annee)
            ->where('id_campus', '=', $campusId)
            ->where('id_cycle', '=', $idCycle)
            ->where('id_classe', '=', $idClasse)
            ->where('id_nniveau', '=', $idNniveau)
            ->where('desinscrire', '=', 0)
            ->first();

        if (!$inscription) {
            throw new \Exception('Aucune inscription active trouvee pour cet etudiant dans ce campus/cycle/specialite/niveau.');
        }

        $classeMatiere = $this->findNoteImportClasseMatiere($row, $idClasse, $idCycle, $idNniveau, $idMatiere);
        $sessionExam = $this->findNoteImportSession($row, $classeMatiere, $idMatiere, $annee);
        $storedNote = $this->calculateImportedNote($rawNote, $sequence, $sessionExam);

        $query = note::where('id_eleve', '=', $student->id)
            ->where('id_matiere', '=', $idMatiere)
            ->where('sequence', '=', $sequence)
            ->where('annee_scolaire', '=', $annee)
            ->where('id_classe', '=', $idClasse);

        if ($noteHasCampus) {
            $query->where('id_campus', '=', $campusId);
        }
        if ($sessionExam) {
            $query->where('id_session', '=', $sessionExam->id);
        } elseif ($classeMatiere) {
            $query->where('id_classe_matiere', '=', $classeMatiere->id);
        }

        $note = $query->first();
        $action = $note ? 'updated' : 'created';
        if (!$note) {
            $note = new note();
            $note->id_creator = Auth::check() ? Auth::user()->id : null;
            $note->edition_details = 'import create: note=' . $storedNote . ' (saisie=' . $rawNote . '/20)';
        } else {
            $note->edition_details = 'import update: old=' . $note->note . ', new=' . $storedNote . ' (saisie=' . $rawNote . '/20)';
        }

        $note->id_eleve = $student->id;
        $note->id_matiere = $idMatiere;
        $note->sequence = $sequence;
        $note->note = $storedNote;
        $note->annee_scolaire = $annee;
        $note->id_classe = $idClasse;
        if ($noteHasCampus) {
            $note->id_campus = $campusId;
        }
        if ($classeMatiere) {
            $note->id_classe_matiere = $classeMatiere->id;
        }
        if ($sessionExam) {
            $note->id_session = $sessionExam->id;
        }
        $note->id_last_editor = Auth::check() ? Auth::user()->id : null;
        $note->save();

        return $action;
    }

    private function findNoteImportStudent($row)
    {
        if ($this->hasImportValue($row, 'id_eleve')) {
            $student = eleve::find((int)$row['id_eleve']);
        } elseif ($this->hasImportValue($row, 'matricule')) {
            $student = eleve::where('matricule', '=', trim($row['matricule']))->first();
        } else {
            throw new \Exception('id_eleve ou matricule est obligatoire.');
        }

        if (!$student) {
            throw new \Exception('Etudiant introuvable.');
        }

        return $student;
    }

    private function findNoteImportClasseMatiere($row, $idClasse, $idCycle, $idNniveau, $idMatiere)
    {
        if ($this->hasImportValue($row, 'id_classe_matiere')) {
            $classeMatiere = classeMatiere::find((int)$row['id_classe_matiere']);
            if (!$classeMatiere) {
                throw new \Exception('classe_matiere introuvable.');
            }
            if ((int)$classeMatiere->id_classe !== (int)$idClasse || (int)$classeMatiere->id_matiere !== (int)$idMatiere) {
                throw new \Exception('classe_matiere ne correspond pas a la specialite/matiere.');
            }
            return $classeMatiere;
        }

        return classeMatiere::where('id_classe', '=', $idClasse)
            ->where('id_cycle', '=', $idCycle)
            ->where('id_nniveau', '=', $idNniveau)
            ->where('id_matiere', '=', $idMatiere)
            ->first();
    }

    private function findNoteImportSession($row, $classeMatiere, $idMatiere, $annee)
    {
        if ($this->hasImportValue($row, 'id_session')) {
            $session = Session_exam::find((int)$row['id_session']);
            if (!$session) {
                throw new \Exception('Session examen introuvable.');
            }
            if ($classeMatiere && (int)$session->id_classe_matiere !== (int)$classeMatiere->id) {
                throw new \Exception('La session examen ne correspond pas au programme classe-matiere.');
            }
            if ((int)$session->id_matiere !== (int)$idMatiere) {
                throw new \Exception('La session examen ne correspond pas a la matiere.');
            }
            return $session;
        }

        if (!$classeMatiere) {
            return null;
        }

        return Session_exam::where('id_classe_matiere', '=', $classeMatiere->id)
            ->where('id_matiere', '=', $idMatiere)
            ->where('annee_academique', '=', $annee)
            ->first();
    }

    private function calculateImportedNote($rawNote, $sequence, $sessionExam)
    {
        if (!$sessionExam) {
            return $rawNote;
        }

        $columns = array(1 => 'cc1', 2 => 'cc2', 3 => 'sn1', 4 => 'sn2', 5 => 'ratrappage1', 6 => 'ratrappage2', 7 => 'tpe1', 8 => 'tpe2');
        if (!isset($columns[$sequence])) {
            return $rawNote;
        }

        $percentage = (float)$sessionExam->{$columns[$sequence]};
        if ($percentage <= 0) {
            return $rawNote;
        }

        return round(($rawNote * $percentage) / 20, 2);
    }

    private function readNoteImportRows($file)
    {
        $extension = strtolower($file->getClientOriginalExtension());
        if ($extension == 'xlsx') {
            return $this->readNoteXlsxRows($file->getRealPath());
        }

        return $this->readNoteCsvRows($file->getRealPath());
    }

    private function readNoteCsvRows($path)
    {
        $sample = file_get_contents($path, false, null, 0, 2048);
        $delimiter = substr_count($sample, ';') >= substr_count($sample, ',') ? ';' : ',';
        $handle = fopen($path, 'r');
        if (!$handle) {
            throw new \Exception('Impossible de lire le fichier.');
        }

        $headers = null;
        $rows = array();
        $line = 0;
        while (($data = fgetcsv($handle, 0, $delimiter)) !== false) {
            $line++;
            if ($this->isEmptyImportRow($data)) {
                continue;
            }
            if (!$headers) {
                $headers = $this->normalizeNoteImportHeaders($data);
                continue;
            }
            $rows[$line] = $this->combineNoteImportRow($headers, $data);
        }
        fclose($handle);

        return $rows;
    }

    private function readNoteXlsxRows($path)
    {
        if (!class_exists('ZipArchive')) {
            throw new \Exception('Le serveur ne peut pas lire les XLSX. Utiliser le template CSV.');
        }

        $zip = new \ZipArchive();
        if ($zip->open($path) !== true) {
            throw new \Exception('Impossible d ouvrir le fichier XLSX.');
        }

        $sharedStrings = $this->readNoteXlsxSharedStrings($zip);
        $sheetXml = $zip->getFromName('xl/worksheets/sheet1.xml');
        $zip->close();

        if (!$sheetXml) {
            throw new \Exception('La premiere feuille du XLSX est introuvable.');
        }

        $sheet = simplexml_load_string($sheetXml);
        $headers = null;
        $rows = array();
        foreach ($sheet->sheetData->row as $rowNode) {
            $rowIndex = (int)$rowNode['r'];
            $values = array();
            foreach ($rowNode->c as $cell) {
                $columnIndex = $this->noteXlsxColumnIndex((string)$cell['r']);
                $value = '';
                if (isset($cell->v)) {
                    $value = (string)$cell->v;
                    if ((string)$cell['t'] == 's') {
                        $value = isset($sharedStrings[(int)$value]) ? $sharedStrings[(int)$value] : '';
                    }
                } elseif (isset($cell->is->t)) {
                    $value = (string)$cell->is->t;
                }
                $values[$columnIndex] = $value;
            }
            if ($this->isEmptyImportRow($values)) {
                continue;
            }
            ksort($values);
            $values = $this->normalizeNoteXlsxRowIndexes($values);
            if (!$headers) {
                $headers = $this->normalizeNoteImportHeaders($values);
                continue;
            }
            $rows[$rowIndex] = $this->combineNoteImportRow($headers, $values);
        }

        return $rows;
    }

    private function readNoteXlsxSharedStrings($zip)
    {
        $xml = $zip->getFromName('xl/sharedStrings.xml');
        if (!$xml) {
            return array();
        }

        $strings = array();
        $shared = simplexml_load_string($xml);
        foreach ($shared->si as $si) {
            if (isset($si->t)) {
                $strings[] = (string)$si->t;
            } else {
                $text = '';
                foreach ($si->r as $run) {
                    $text .= (string)$run->t;
                }
                $strings[] = $text;
            }
        }

        return $strings;
    }

    private function noteXlsxColumnIndex($cellRef)
    {
        preg_match('/^[A-Z]+/', $cellRef, $matches);
        $letters = isset($matches[0]) ? $matches[0] : 'A';
        $index = 0;
        for ($i = 0; $i < strlen($letters); $i++) {
            $index = $index * 26 + (ord($letters[$i]) - 64);
        }
        return $index - 1;
    }

    private function normalizeNoteXlsxRowIndexes($values)
    {
        $max = count($values) ? max(array_keys($values)) : -1;
        $row = array();
        for ($i = 0; $i <= $max; $i++) {
            $row[] = isset($values[$i]) ? $values[$i] : '';
        }
        return $row;
    }

    private function normalizeNoteImportHeaders($headers)
    {
        return array_map(function ($header) {
            $header = strtolower(trim($header));
            $header = preg_replace('/[^a-z0-9]+/', '_', $header);
            return trim($header, '_');
        }, $headers);
    }

    private function combineNoteImportRow($headers, $data)
    {
        $row = array();
        foreach ($headers as $index => $header) {
            if ($header === '') {
                continue;
            }
            $row[$header] = isset($data[$index]) ? trim($data[$index]) : '';
        }
        return $row;
    }

    private function isEmptyImportRow($data)
    {
        foreach ($data as $value) {
            if (trim((string)$value) !== '') {
                return false;
            }
        }
        return true;
    }

    private function hasImportValue($row, $key)
    {
        return isset($row[$key]) && trim((string)$row[$key]) !== '';
    }

    private function valueOrDefault($row, $key, $default)
    {
        return $this->hasImportValue($row, $key) ? trim($row[$key]) : $default;
    }

    private function requiredImportInt($row, $key)
    {
        if (!$this->hasImportValue($row, $key) || !is_numeric($row[$key])) {
            throw new \Exception($key.' est obligatoire et doit etre numerique.');
        }
        return (int)$row[$key];
    }

    private function requiredImportNumber($row, $key)
    {
        if (!$this->hasImportValue($row, $key)) {
            throw new \Exception($key.' est obligatoire.');
        }
        $value = str_replace(',', '.', $row[$key]);
        if (!is_numeric($value)) {
            throw new \Exception($key.' doit etre numerique.');
        }
        return (float)$value;
    }

