            $m_cps = $gm->fetch('id_matiere_mere')->toArray();


            foreach ($cm as $entry) {
                if (!($this->isIn($entry->id_matiere, $m_cps)))
                    $sCoef += $entry->coef;
            }
            $matiere_list = $cm->fetch('id_matiere')->toArray();
            $m = matiere::whereIn('id', $matiere_list)->whereIn('id', $matieres_pv)->whereNotIn('id', $m_cps)->get();


            $k = 0;
            foreach ($e as $eleve) {

                $l = 0;
                $sNote = 0;
