                $idelevess = 0;

                foreach ($m as $matiere) {
                    $cps = false;
                    $cpst = false;

                    if ($this->isIn($matiere->id, $m_cps)) {
                        $cps = true;

                    }

                    $credit = $cm->where('id_matiere', $matiere->id)
                        ->first()
